  POS_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  NOTCH: "http://ihris.org/fhir/StructureDefinition/notch",
  SALARY_GRADE_REF: "http://ihris.org/fhir/StructureDefinition/salary-grade",
  SALARY_AMOUNT: "http://ihris.org/fhir/StructureDefinition/ls-salary-amount",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  // Position change reason extensions
  CHANGE_REASON: "http://ihris.org/fhir/StructureDefinition/change-reason",
  PREV_POSITION: "http://ihris.org/fhir/StructureDefinition/previous-position",
  CHANGE_DATE: "http://ihris.org/fhir/StructureDefinition/change-date",
  // Role departure (RoleDepartureProfile) extensions
  DEPARTURE_DATE: "http://ihris.org/fhir/StructureDefinition/departure-date",
  DEPARTURE_REASON:
