        facility: "",
        council: "",
        district: "",
        employmentCategory: "",
        startDate: null,
        endDate: null,
        offerType: "",
        supervisor: {},
        isHOD: false,
        hodLocation: "",
        hodType: "",
        isDepartmentalDirector: false,
