      // record on file).
      departure: null,

      changeHeaders: [
        {
          text: "Previous Position",
          value: "previousPosition",
          sortable: false,
        },
        { text: "Change Reason", value: "reason", sortable: false },
        { text: "Date", value: "date", sortable: false, width: 130 },
      ],
    };
  },

  computed: {
    initials() {
      return this.getInitials(this.practitionerName);
    },
  },

  async mounted() {
    await this.loadAll();
  },

  methods: {
    // ── Orchestration ──────────────────────────────────────────────────
    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        await Promise.all([this.loadRole(), this.loadPractitioner()]);
        // Salaries and change reasons share one FHIR query
        await this.loadBasicRecords();
      } catch (err) {
        console.error("PositionView loadAll error", err);
        this.error = "Failed to load position details. Please try again.";
      } finally {
        this.loading = false;
      }
    },

    // ── PractitionerRole ───────────────────────────────────────────────
    async loadRole() {
      const res = await fetch(`/fhir/PractitionerRole/${this.queries.role}`);
      const data = await res.json();

      // Strict === true, not "!== false" - a role should only ever read as
      // Active when the field genuinely says so, not by defaulting an
      // absent/undefined value to active. Matches the same active === true
      // check assignPosition.js/terminatePosition.js and the FSH action
      // conditions now use everywhere else.
      this.role.active = data.active === true;
      this.role.startDate = data.period?.start || null;
      this.role.endDate = data.period?.end || null;

      // Employment category
      const empCat = this.getExt(data, EXT.EMP_CAT, "valueCoding");
      this.role.employmentCategory = empCat?.display || empCat?.code || "";

      // Offer type
      const offerType = this.getExt(data, EXT.OFFER_TYPE, "valueCoding");
      this.role.offerType = offerType?.display || offerType?.code || "";

      // HOD — URL is "is-hod", details in "hod-details" nested extension
      const hodCoding = this.getExt(data, EXT.IS_HOD, "valueCoding");
      this.role.isHOD = hodCoding?.code === "yes";
      if (this.role.isHOD) {
        const hodDetailsExt = data.extension?.find(
          (e) => e.url === EXT.HOD_DETAILS,
        );
        if (hodDetailsExt) {
          // type sub-extension: valueString "district" | "facility"
          const typeExt = hodDetailsExt.extension?.find(
            (e) => e.url === "type",
          );
          this.role.hodType = typeExt?.valueString || "";

          // location sub-extension: valueReference to a Location
          const locExt = hodDetailsExt.extension?.find(
            (e) => e.url === "location",
          );
          const locRef = locExt?.valueReference?.reference;
          if (locRef) {
            try {
              const locRes = await fetch(`/fhir/${locRef}`);
              const locData = await locRes.json();
              this.role.hodLocation =
                locData.name || locExt?.valueReference?.display || locRef;
            } catch (_) {
              this.role.hodLocation = locExt?.valueReference?.display || locRef;
            }
          }
        }
      }

      // Departmental Director
      const departmentalDirectorCoding = this.getExt(
        data,
        EXT.IS_DEPARTMENTAL_DIRECTOR,
        "valueCoding",
      );
      this.role.isDepartmentalDirector =
        departmentalDirectorCoding?.code === "yes";

      // Supervisor — bare Practitioner reference, must fetch name
      const supRef = this.getExt(data, EXT.SUPERVISOR, "valueReference");
      if (supRef?.reference) {
        try {
          let response = await fetch(
            "/fhir/PractitionerRole?practitioner=" +
              supRef.reference +
              "&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition",
          );
          response = await response.json();
          let supervisorPract = response.entry.find(
            (entry) => entry.resource.resourceType === "Practitioner",
          )?.resource;
          // let supervisorRole = response.entry.find((entry) => entry.resource.resourceType === 'PractitionerRole')?.resource
          let supervisorPos = response.entry.find((entry) =>
            entry.resource.meta.profile.includes(
              "http://ihris.org/fhir/StructureDefinition/position-profile",
            ),
          )?.resource;
          let designationId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/designation"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (designationId) {
            response = await fetch("/fhir/Basic/" + designationId);
            response = await response.json();
            this.role.supervisor.position =
              response?.extension?.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                );
              })?.valueString || "";
          }

          let facilityId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url === "http://ihris.org/fhir/StructureDefinition/facility"
              );
            })
            ?.valueReference?.reference?.split("/")?.[1];
          if (facilityId) {
            response = await fetch("/fhir/Location/" + facilityId);
            response = await response.json();
            this.role.supervisor.facility = response.name;
          }

          let gradeId = supervisorPos.extension
            ?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/salary-grade"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          if (gradeId) {
            response = await fetch("/fhir/Basic/" + gradeId);
            response = await response.json();
            this.role.supervisor.grade = response?.extension?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString;
          }
          this.role.supervisor.name = this.parsePractitionerName(
            supervisorPract,
          );
        } catch (err) {
          console.log(err);
        }
      }

      // Position Basic → designation + department
      const posRef = this.getExt(data, EXT.POSITION, "valueReference");
      if (posRef?.reference) {
        try {
          const posId = posRef.reference.split("/")[1];
          const posRes = await fetch(`/fhir/Basic/${posId}`);
          const posData = await posRes.json();
          const facilityRef = posData.extension.find(
            (ext) =>
              ext.url === "http://ihris.org/fhir/StructureDefinition/facility",
          )?.valueReference?.reference;
          if (facilityRef) {
            await this.loadFacilityHierarchy(facilityRef);
          }
          await this.enrichPosition(posData);
        } catch (_) {
          this.role.designation = posRef.display || posRef.reference;
        }
      }
    },

    // ── Facility → Council → District hierarchy ────────────────────────
    async loadFacilityHierarchy(facilityRef) {
      try {
        const facRes = await fetch(`/fhir/${facilityRef}`);
        const facData = await facRes.json();
        this.role.facility = facData.name || facilityRef;

        // partOf → council
        const councilRef = facData.partOf?.reference;
        if (councilRef) {
          try {
            const councilRes = await fetch(`/fhir/${councilRef}`);
            const councilData = await councilRes.json();
            this.role.council = councilData.name || councilRef;

            // partOf → district
            const districtRef = councilData.partOf?.reference;
            if (districtRef) {
              try {
                const districtRes = await fetch(`/fhir/${districtRef}`);
                const districtData = await districtRes.json();
                this.role.district = districtData.name || districtRef;
              } catch (err) {
                console.log(err);
              }
            }
          } catch (err) {
            console.log(err);
          }
        }
      } catch (err) {
        console.log(err);
        this.role.facility = facilityRef;
      }
    },

    async enrichPosition(posData) {
      // Designation — follows a valueReference to another Basic
      const desigRef = this.getExt(posData, EXT.DESIGNATION, "valueReference");
      if (desigRef?.reference) {
        try {
          const desigId = desigRef.reference.split("/")[1];
          const desigRes = await fetch(`/fhir/Basic/${desigId}`);
          const desigData = await desigRes.json();
          this.role.designation =
            this.getExt(desigData, EXT.POS_NAME, "valueString") ||
            desigRef.display ||
            "";
        } catch (_) {
          this.role.designation = desigRef.display || "";
        }
      }

      // Department
      const deptCoding = this.getExt(posData, EXT.DEPARTMENT, "valueCoding");
      this.role.department = deptCoding?.display || deptCoding?.code || "";
    },

    // ── Practitioner name ──────────────────────────────────────────────
    async loadPractitioner() {
      try {
        const res = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const data = await res.json();
        this.practitionerName = this.parsePractitionerName(data);
      } catch (_) {
        this.practitionerName = `Practitioner/${this.queries.practitioner}`;
      }
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },

    // ── Basic records: salaries + position change reasons ──────────────
    async loadBasicRecords() {
      this.loadingSalaries = true;
      try {
        const res = await fetch(
          `/fhir/Basic?practitionerrole=PractitionerRole/${this.queries.role}&_count=100&_sort=-_lastUpdated`,
        );
        const data = await res.json();
        const entries = (data.entry || []).map((e) => e.resource);

        const salaryResources = entries.filter((r) =>
          r.meta?.profile?.some((p) => p === SALARY_PROFILE),
        );
        const changeResources = entries.filter((r) =>
          r.meta?.profile?.some((p) => p === CHANGE_PROFILE),
        );
        const departureResource = entries.find((r) =>
          r.meta?.profile?.some((p) => p === DEPARTURE_PROFILE),
        );

        // Process salaries in parallel
        this.salaries = await Promise.all(
          salaryResources.map((r) => this.parseSalary(r)),
        );

        // Process change reasons
        this.positionChanges = await Promise.all(
          changeResources.map((r) => this.parseChangeReason(r)),
        );

        // Departure - at most one record per role
        this.departure = departureResource
          ? await this.parseDeparture(departureResource)
          : null;
      } catch (err) {
        console.error("loadBasicRecords error", err);
      } finally {
        this.loadingSalaries = false;
      }
    },

    async parseSalary(resource) {
      const entry = {
        id: resource.id,
        effectiveDate:
          this.getExt(resource, EXT.SALARY_START, "valueDate") || null,
        notch: "",
        grade: "",
        amount: "",
      };

      const notchRef = this.getExt(
        resource,
        EXT.SALARY_NOTCH,
        "valueReference",
      );
      if (!notchRef?.reference) return entry;

      try {
        const notchRes = await fetch(`/fhir/${notchRef.reference}`);
        const notchData = await notchRes.json();

        // Notch name
        const notchCoding = this.getExt(notchData, EXT.NOTCH, "valueCoding");
        entry.notch =
          notchCoding?.display || notchCoding?.code || notchRef.display || "";

        // Amount
        const amountExt = notchData.extension?.find(
          (x) => x.url === EXT.SALARY_AMOUNT,
        );
        const money = amountExt?.valueMoney;
        if (money) {
          entry.amount = `${money.currency} ${Number(
            money.value,
          ).toLocaleString()}`;
        }

        // Grade
        const gradeRef = this.getExt(
          notchData,
          EXT.SALARY_GRADE_REF,
          "valueReference",
        );
        if (gradeRef?.display) {
          entry.grade = gradeRef.display;
        } else if (gradeRef?.reference) {
          try {
            const gradeRes = await fetch(`/fhir/${gradeRef.reference}`);
            const gradeData = await gradeRes.json();
            entry.grade =
              this.getExt(gradeData, EXT.POS_NAME, "valueString") ||
              gradeRef.reference;
          } catch (_) {
            entry.grade = gradeRef.reference;
          }
        }
      } catch (_) {
        entry.notch = notchRef.display || notchRef.reference;
      }

      return entry;
    },

    async parseChangeReason(resource) {
      const entry = {
        id: resource.id,
        previousPosition: "",
        reason: "",
        date:
          this.getExt(resource, EXT.CHANGE_DATE, "valueDate") ||
          this.getExt(resource, EXT.CHANGE_DATE, "valueDateTime") ||
          null,
      };

      const reasonCoding = this.getExt(
        resource,
        EXT.CHANGE_REASON,
        "valueCoding",
      );
      entry.reason = reasonCoding?.display || reasonCoding?.code || "";

      const prevPosRef = this.getExt(
        resource,
        EXT.PREV_POSITION,
        "valueReference",
      );
      if (prevPosRef?.display) {
        entry.previousPosition = prevPosRef.display;
      } else if (prevPosRef?.reference) {
        try {
          const posId = prevPosRef.reference.split("/")[1];
          const posRes = await fetch(`/fhir/Basic/${posId}`);
          const posData = await posRes.json();
          const desigRef = this.getExt(
            posData,
            EXT.DESIGNATION,
            "valueReference",
          );
          if (desigRef?.reference) {
            const desigId = desigRef.reference.split("/")[1];
            const desigRes = await fetch(`/fhir/Basic/${desigId}`);
            const desigData = await desigRes.json();
            entry.previousPosition =
              this.getExt(desigData, EXT.POS_NAME, "valueString") ||
              desigRef.display ||
              prevPosRef.reference;
          } else {
            entry.previousPosition =
              this.getExt(posData, EXT.POS_NAME, "valueString") ||
              prevPosRef.reference;
          }
        } catch (_) {
          entry.previousPosition = prevPosRef.reference;
        }
      }

      return entry;
    },

    // ── Role departure (RoleDepartureProfile) ───────────────────────────
    async parseDeparture(resource) {
      const reasonCoding = this.getExt(
        resource,
        EXT.DEPARTURE_REASON,
        "valueCoding",
      );
      const entry = {
        date: this.getExt(resource, EXT.DEPARTURE_DATE, "valueDate") || null,
        reason: reasonCoding?.display || reasonCoding?.code || "",
        reasonCode: reasonCoding?.code || "",
        dismissalReason:
          this.getExt(resource, EXT.DISMISAL_REASON, "valueString") || "",
        // resignation-reason is 0..* on ResignationDetails - a resignation
        // can carry more than one reason, so this collects all of them
        // rather than just the first (was using .find(), silently dropping
        // every reason after the first).
        resignationReasons: [],
        resignationReasonOther: "",
        transferFacility: "",
      };

      const resignationExt = resource.extension?.find(
        (e) => e.url === EXT.RESIGNATION_DETAILS,
      );
      if (resignationExt) {
        entry.resignationReasons = (resignationExt.extension || [])
          .filter((e) => e.url === "resignation-reason")
          .map((e) => e.valueCoding?.display || e.valueCoding?.code)
          .filter(Boolean);
        const otherSub = resignationExt.extension?.find(
          (e) => e.url === "resignation-reason-other",
        );
        entry.resignationReasonOther = otherSub?.valueString || "";
      }

      const transferExt = resource.extension?.find(
        (e) => e.url === EXT.TRANSFER_OUT_DETAILS,
      );
      const facilityRef = transferExt?.extension?.find(
        (e) => e.url === "facility",
      )?.valueReference;
      if (facilityRef?.reference) {
        try {
          const facRes = await fetch(`/fhir/${facilityRef.reference}`);
          const facData = await facRes.json();
          entry.transferFacility = facData.name || facilityRef.display || "";
        } catch (_) {
          entry.transferFacility = facilityRef.display || "";
        }
      }

      return entry;
    },

    // ── Helpers ────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    getInitials(name = "") {
      return name
        ?.split(" ")
        ?.filter(Boolean)
        ?.slice(0, 2)
        ?.map((w) => w[0].toUpperCase())
        ?.join("");
    },
  },
};
</script>

